state.plans=state.plans&&typeof state.plans==='object'?state.plans:{};
state.studyTime=Array.isArray(state.studyTime)?state.studyTime:[];
state.stepEvidence=state.stepEvidence&&typeof state.stepEvidence==='object'?state.stepEvidence:{};
const phaseModel=[
 {name:'現在地を知る',weight:5,goal:'未学習・既習・苦手な分野を整理し、学ぶ範囲と週の時間を決める。'},
 {name:'仕組みを理解',weight:25,goal:'用語や原則を、自分の言葉と具体例で説明できるようにする。'},
 {name:'基礎を反復',weight:30,goal:'論点ごとの初見の基本問題を、ヒントなしで解く。'},
 {name:'条件を変えて応用',weight:20,goal:'条件の異なる類題・複数論点の問題で、処理の理由を説明する。'},
 {name:'時間内に解く',weight:15,goal:'本試験形式・制限時間で総合問題を解き、分野別の失点を見直す。'},
 {name:'日をあけて再確認',weight:5,goal:'7日以上あけて解き直し、まだ残る弱点を前の段階へ戻して練習する。'}
];
function planKey(){normalizeTarget();return exam==='uscpa'?'uscpa:four':exam+':'+curriculumUnit}
function referenceHours(){if(exam==='nissho'){const ranges={3:[60,80],2:[200,250],1:[500,600]};const [min,max]=ranges[curriculumUnit];return {min,max,defaultHours:(min+max)/2,label:'TAC公表の学習時間目安（授業込み）',condition:curriculumUnit===3?'3級の学習全体':curriculumUnit===2?'3級レベルの知識がある場合の2級学習':'2級レベルの知識がある場合の1級学習',url:'https://www.tac-school.co.jp/kouza_boki/boki_faq_index.html'}}if(exam==='uscpa')return {min:1200,max:1500,defaultHours:1350,label:'アビタス公表の学習時間目安（講義込み）',condition:'FAR・AUD・REGと選択1科目の合計。1科目分ではありません。',url:'https://www2.abitus.co.jp/uscpa/faq/'};return {min:null,max:null,defaultHours:null,label:'全経の信頼できる平均学習時間は確認できていません',condition:'全経の計画時間は、前提知識や教材に合わせてご自身で設定してください。日商の値を全経の平均として流用しません。',url:'https://www.zenkei.or.jp/exam/bookkeeping'}}
function currentPlan(){const ref=referenceHours(),p=state.plans[planKey()]||{};return {hours:p.hours??ref.defaultHours,weekly:p.weekly??10,deadline:p.deadline||'',discipline:p.discipline||'BAR'}}
function planScope(){const p=currentPlan();return exam==='uscpa'?['FAR','AUD','REG',p.discipline].flatMap(unit=>curriculum.filter(t=>t.exam===exam&&t.unit===unit)):curriculum.filter(t=>t.exam===exam&&String(t.unit)===String(curriculumUnit))}
function smallSteps(){const groups=new Map();planScope().forEach(t=>{const k=t.unit+' / '+t.area;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(t)});const chunks=[];for(const [area,items] of groups)for(let i=0;i<items.length;i+=5){const topics=items.slice(i,i+5);chunks.push({id:planKey()+':'+topics[0].id,area,topics})}return chunks}
function minutesForPlan(){return state.studyTime.filter(t=>t.key===planKey()).reduce((s,t)=>s+t.minutes,0)}
function validCount(n){return Number.isInteger(n)&&n>=10&&n<=10000}
function passingScore(n,c){return validCount(n)&&Number.isInteger(c)&&c>=0&&c<=n&&c/n>=.8}
function stepStatus(chunk){const e=state.stepEvidence[chunk.id]||{},understood=chunk.topics.every(t=>progressOf(t)===2),basic=passingScore(e.basicTotal,e.basicCorrect),gap=e.basicDate&&e.retestDate?(Date.parse(e.retestDate+'T12:00:00Z')-Date.parse(e.basicDate+'T12:00:00Z'))/86400000:0,retained=passingScore(e.retestTotal,e.retestCorrect)&&gap>=7;return {understood,basic,retained,complete:understood&&basic&&retained}}
function dateAfterWeeks(weeks){if(!Number.isFinite(weeks))return '未設定';const d=new Date();d.setDate(d.getDate()+Math.ceil(weeks*7));return d.toLocaleDateString('ja-JP')}
function scheduleMetrics(p=currentPlan()){const spent=minutesForPlan()/60,remaining=p.hours?Math.max(0,p.hours-spent):null,weeks=remaining===null?null:remaining/p.weekly,days=p.deadline?Math.ceil((Date.parse(p.deadline+'T23:59:59Z')-Date.now())/86400000):null,required=remaining===null||!days||days<0?null:remaining/(days/7);return {spent,remaining,weeks,days,required}}
function renderStudyPlan(){normalizeTarget();const host=$('studyplanbody');if(!host)return;const ref=referenceHours(),p=currentPlan(),m=scheduleMetrics(p),chunks=smallSteps(),complete=chunks.filter(c=>stepStatus(c).complete).length,next=chunks.find(c=>!stepStatus(c).complete),pastWeek=state.studyTime.filter(t=>t.key===planKey()&&Date.now()-t.time<7*86400000).reduce((s,t)=>s+t.minutes,0)/60;
 host.innerHTML=`<div class="topline"><span class="eyebrow">YOUR LEARNING STAIRCASE</span></div><h1>一段ずつ、できることを増やす。</h1><p class="intro">時間で見通しをつくり、理解を確かめて次の段へ。${esc(catalogs[exam].name)} ${exam==='uscpa'?'必須3科目＋選択1科目':esc(unitLabel(curriculumUnit))}の学習計画。</p><div class="plan-card"><div class="sectiontitle"><h2>自分の学習ペースを決める</h2><span class="muted">出典確認：2026.10.23</span></div><div class="source-box"><b>${esc(ref.label)}</b><p>${ref.min?ref.min.toLocaleString()+'〜'+ref.max.toLocaleString()+'時間 / ':''}${esc(ref.condition)}</p><a href="${ref.url}" target="_blank" rel="noopener">参考資料を読む ↗</a><p>学習時間には個人差があります。公表値は当サイト利用者の実測平均ではありません。初期計画には範囲の中間値を使用し、必要に応じて変更できます。</p></div><form id="planform" class="plan-form"><label>計画する合計時間<input id="planhours" type="number" min="1" max="20000" step="0.5" required value="${p.hours??''}" placeholder="例：300"><small>時間 / 前提学習が必要なら加えて設定</small></label><label>1週間の学習時間<input id="planweekly" type="number" min="0.5" max="100" step="0.5" required value="${p.weekly}"><small>時間 / 続けられるペースで</small></label><label>目標日（任意）<input id="plandeadline" type="date" min="${day()}" value="${esc(p.deadline)}"><small>試験日や、学習を一区切りにする日</small></label>${exam==='uscpa'?`<label>受験する選択科目<select id="plandiscipline">${['BAR','ISC','TCP'].map(d=>`<option ${d===p.discipline?'selected':''}>${d}</option>`).join('')}</select><small>選ばなかった2科目は計画に含めません</small></label>`:''}<button class="primary" type="submit">学習計画を保存 →</button></form><p class="scope-note" id="planmessage" role="status"></p><div class="scope-metrics"><div><strong>${m.spent.toFixed(1)}h</strong><span>記録した学習時間</span></div><div><strong>${m.weeks===null?'—':Math.ceil(m.weeks)+'週'}</strong><span>残りの計画時間を終える目安</span></div><div><strong>${pastWeek.toFixed(1)} / ${p.weekly}h</strong><span>直近7日間の学習実績</span></div><div><strong>${complete} / ${chunks.length}</strong><span>到達条件を満たした小ステップ</span></div></div><p class="scope-note">このペースで計画時間に達する日：${m.weeks===null?'合計時間を設定してください':dateAfterWeeks(m.weeks)}。合格日や教材の完成予定日を示すものではありません。</p>${m.required!==null?`<p class="plan-alert">目標日までの必要ペース：約${m.required.toFixed(1)}時間／週。${m.required>p.weekly?'設定した週の時間を上回っています。目標日や時間を調整しましょう。':'設定した週の時間で計画時間を確保できます。到達状況も合わせて確認しましょう。'}</p>`:p.deadline&&m.days<=0?'<p class="plan-alert">目標日を過ぎています。実績を確認し、計画を見直しましょう。</p>':''}</div>
 <div class="sectiontitle"><h2>大きな流れを、6つの段階に。</h2></div><ol class="learning-stairs">${phaseModel.map((ph,i)=>`<li style="--step:${i}"><span class="eyebrow">PHASE 0${i+1}</span><h3>${ph.name}</h3><p>${ph.goal}</p><small>${p.hours?Math.round(p.hours*ph.weight/100*10)/10+'時間':''} / 配分 ${ph.weight}%</small></li>`).join('')}</ol><p class="scope-note">時間配分はIL MASTROの計画用の仮配分です。実測平均ではありません。各段階は行き来でき、時間を使っただけでは修了扱いにしません。</p>
 <div class="plan-card"><h2>今日の、一段。</h2>${next?`<p>${esc(next.area)}</p><p>${esc(next.topics[0].title)}${next.topics.length>1?' ほか'+(next.topics.length-1)+'項目':''}</p><div class="statusactions"><button class="primary" id="nextsmallstep">このステップを確認 →</button><button class="textbtn" id="planmap">全体の学習項目を見る ↗</button></div>`:'<p>各ステップの自己記録が揃いました。初見の総合問題と制限時間で、理解を確かめましょう。</p>'}<p class="scope-note">一度の学習は15〜25分を区切りの目安にできます。問題の難しさに合わせて延長・休憩し、自分のペースを優先してください。</p></div>
 <div class="sectiontitle"><h2>小さなステップを積み上げる</h2><span class="muted">1ステップ最大5項目</span></div><p class="scope-note">次の目標と到達条件を明確にする段階学習です。ステップ数は試験と学習範囲から決まり、55段階に固定しません。確認基準の80%はサイト内の学習目標で、公式の合格基準ではありません。</p><div class="smallsteps">${chunks.map((ch,i)=>{const ss=stepStatus(ch);return `<button class="smallstep ${ss.complete?'complete':''}" data-smallstep="${esc(ch.id)}"><span class="step-number">${String(i+1).padStart(2,'0')}</span><span><b>${esc(ch.topics[0].title)}</b><small>${ch.topics.length}項目 / ${ss.complete?'到達条件を記録済み':ss.understood?'基礎・再テストを確認':'説明できるようにする'}</small></span><span>${ss.complete?'✓':'↗'}</span></button>`}).join('')}</div><div id="smallsteppanel"></div>
 <div class="plan-card"><h2>積み重ねた時間を記録する</h2><p class="scope-note">サイト外の講義・教材・演習も含めて、実際に取り組んだ時間を記録できます。</p><form id="timeform" class="plan-form"><label>学習時間（分）<input id="studyminutes" type="number" min="1" max="1440" step="1" required placeholder="例：25"></label><label>取り組んだ段階<select id="studyphase">${phaseModel.map((ph,i)=>`<option value="${i}">${ph.name}</option>`).join('')}</select></label><button class="primary" type="submit">学習時間を記録 ＋</button></form><p role="status" id="timemessage"></p><div class="time-records">${state.studyTime.filter(t=>t.key===planKey()).slice(-5).reverse().map(t=>`<div><span>${new Date(t.time).toLocaleDateString('ja-JP')} / ${phaseModel[t.phase]?.name||'学習'} / ${t.minutes}分</span><button class="textbtn" data-delete-time="${t.id}">取消</button></div>`).join('')}</div></div><details class="source-box"><summary>設計の参考と、このサイトの判定について</summary><p>小さな単位で取り組み、理解を確認しながら進む段階学習を参考にしています。IL MASTRO独自の学習計画であり、四谷学院の教材・段階構成・講師による評価を提供するものではありません。</p><a href="https://www.yotsuyagakuin.com/w_teachers/55.html" target="_blank" rel="noopener">四谷学院の公式説明 ↗</a><p>小ステップの結果は本人が入力した記録です。先生による採点・合格判定ではありません。サイト内の教材が未収録の項目も、計画と学習対象に残します。</p></details>`;
 $('planform').onsubmit=e=>{e.preventDefault();const hours=Number($('planhours').value),weekly=Number($('planweekly').value),deadline=$('plandeadline').value;if(!Number.isFinite(hours)||hours<1||hours>20000||!Number.isFinite(weekly)||weekly<.5||weekly>100||deadline&&(!/^\d{4}-\d{2}-\d{2}$/.test(deadline)||deadline<day())){$('planmessage').textContent='時間・目標日を確認してください。';return}state.plans[planKey()]={hours,weekly,deadline,discipline:$('plandiscipline')?.value||p.discipline};save();renderStudyPlan();$('planmessage').textContent='計画を保存しました。実績に合わせていつでも変更できます。'};
 $('timeform').onsubmit=e=>{e.preventDefault();const minutes=Number($('studyminutes').value),phase=Number($('studyphase').value);if(!Number.isInteger(minutes)||minutes<1||minutes>1440||!Number.isInteger(phase)||phase<0||phase>5){$('timemessage').textContent='1〜1440分の整数で入力してください。';return}state.studyTime.push({id:Date.now()+'-'+Math.random().toString(36).slice(2,8),key:planKey(),minutes,phase,time:Date.now()});save();renderStudyPlan();$('timemessage').textContent=minutes+'分の積み重ねを記録しました。'};
 document.querySelectorAll('[data-smallstep]').forEach(b=>b.onclick=()=>openSmallStep(b.dataset.smallstep));document.querySelectorAll('[data-delete-time]').forEach(b=>b.onclick=()=>{state.studyTime=state.studyTime.filter(t=>t.id!==b.dataset.deleteTime);save();renderStudyPlan();$('timemessage').textContent='時間の記録を取り消しました。'});if(next)$('nextsmallstep').onclick=()=>openSmallStep(next.id);if($('planmap'))$('planmap').onclick=()=>navigate('curriculum');
}
function openSmallStep(id){const ch=smallSteps().find(c=>c.id===id);if(!ch)return;const e=state.stepEvidence[id]||{},s=stepStatus(ch),number=smallSteps().findIndex(c=>c.id===id)+1;$('smallsteppanel').innerHTML=`<article class="lesson-card"><span class="eyebrow">SMALL STEP ${String(number).padStart(2,'0')}</span><h2>この一段の、到達条件。</h2><p>${esc(ch.area)}</p><ul class="step-topics">${ch.topics.map(t=>`<li><button class="textbtn" data-step-lesson="${t.id}">${esc(t.title)} ↗</button><small>${statusNames[progressOf(t)]}</small></li>`).join('')}</ul><div class="stages"><span>${s.understood?'✓':'○'} 全項目を自力で説明</span><span>${s.basic?'✓':'○'} 初見の基礎問題80%以上</span><span>${s.retained?'✓':'○'} 7日後の再テスト80%以上</span></div><p class="scope-note">各テスト10問以上。教材・問題番号を控え、解答を見ずに取り組んだ結果を記録します。解説を覚えた同一問題だけではなく、類題も含めてください。</p><form id="evidenceform"><div class="evidence-grid"><fieldset><legend>初見の基礎問題</legend><label>実施日<input type="date" id="basicdate" max="${day()}" value="${esc(e.basicDate||'')}"></label><label>解いた問題数<input id="basictotal" type="number" min="10" max="10000" value="${e.basicTotal??''}"></label><label>正解数<input id="basiccorrect" type="number" min="0" max="10000" value="${e.basicCorrect??''}"></label></fieldset><fieldset><legend>7日以上あけた再テスト</legend><label>実施日<input type="date" id="retestdate" max="${day()}" value="${esc(e.retestDate||'')}"></label><label>解いた問題数<input id="retesttotal" type="number" min="10" max="10000" value="${e.retestTotal??''}"></label><label>正解数<input id="retestcorrect" type="number" min="0" max="10000" value="${e.retestCorrect??''}"></label></fieldset></div><label for="evidencenote">使った教材・問題番号・気づき</label><textarea id="evidencenote" maxlength="3000" rows="3">${esc(e.note||'')}</textarea><button class="primary" type="submit">このステップの記録を保存</button><p id="evidencemessage" role="status"></p></form><p class="scope-note">本人が記録した到達状況です。理解の自己チェックと、この記録の3条件が揃うと小ステップが完了表示になります。時間達成や正答率だけでは完了しません。</p></article>`;
 document.querySelectorAll('[data-step-lesson]').forEach(b=>b.onclick=()=>{navigate('curriculum');openLesson(b.dataset.stepLesson)});$('evidenceform').onsubmit=ev=>{ev.preventDefault();const next={note:$('evidencenote').value};for(const kind of ['basic','retest']){const date=$(kind+'date').value,n=$(kind+'total').value,c=$(kind+'correct').value;if(date||n||c){if(!date||date>day()||!validCount(Number(n))||!Number.isInteger(Number(c))||c===''||Number(c)<0||Number(c)>Number(n)){$('evidencemessage').textContent='日付・問題数（10問以上）・正解数を揃えて確認してください。';return}next[kind+'Date']=date;next[kind+'Total']=Number(n);next[kind+'Correct']=Number(c)}}if(next.retestDate&&!next.basicDate){$('evidencemessage').textContent='再テストの前に、基礎問題の結果を記録してください。';return}if(next.retestDate&&next.retestDate<next.basicDate){$('evidencemessage').textContent='再テストは基礎問題の実施日以降で記録してください。';return}state.stepEvidence[id]=next;save();renderStudyPlan();openSmallStep(id);$('evidencemessage').textContent=stepStatus(ch).complete?'一段、到達条件が揃いました。次の一段へ。':'記録を保存しました。まだの条件をひとつずつ確認しましょう。'};$('smallsteppanel').scrollIntoView?.({behavior:'smooth',block:'start'})
}
